const item = $input.item.json;
const body_data = item.body || item;

const promptText = 'Analizá este flyer publicitario y extraé la siguiente información en formato JSON (solo el JSON, sin texto adicional ni bloques markdown):\n\n{\n  "empresa": "nombre del negocio o persona",\n  "sector": "rubro en 2-3 palabras",\n  "email": "email si aparece, sino null",\n  "telefono": "número sin espacios ni caracteres especiales. Si es argentino y empieza con 11 o 15 agregá 54 al inicio. Solo dígitos. Sino null",\n  "instagram": "handle sin @, sino null",\n  "website": "URL completa con https://, sino null",\n  "descripcion": "qué hace el negocio en 1-2 oraciones cortas"\n}';

const body = {
  model: 'claude-haiku-4-5-20251001',
  max_tokens: 1024,
  messages: [{
    role: 'user',
    content: [
      {
        type: 'image',
        source: {
          type: 'base64',
          media_type: body_data.mimeType || 'image/jpeg',
          data: body_data.image
        }
      },
      {
        type: 'text',
        text: promptText
      }
    ]
  }]
};

return { json: { claudeBody: JSON.stringify(body) } };

const response = $input.item.json;
const text = response.content[0].text;
const clean = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let data;
try {
  data = JSON.parse(clean);
} catch(e) {
  throw new Error('No se pudo parsear la respuesta de visión: ' + text);
}

return { json: data };

const flyerData = $('Parse Flyer Data').item.json;
const websiteInput = $input.item.json;

// Extract website text if the HTTP request succeeded
let websiteContext = '';
if (typeof websiteInput.data === 'string' && websiteInput.data.length > 0) {
  websiteContext = websiteInput.data
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\s+/g, ' ')
    .trim()
    .substring(0, 3000);
}

// Detect contact channel: email > whatsapp > instagram
let canal = 'instagram';
if (flyerData.email) canal = 'email';
else if (flyerData.telefono) canal = 'whatsapp';

const canalLabel = canal === 'email' ? 'email' : canal === 'whatsapp' ? 'WhatsApp' : 'Instagram DM';
const maxLength = canal === 'email' ? '8-10 oraciones' : '3-4 oraciones cortas';
const subjectInstruction = canal === 'email' ? '\n3. Un asunto de email atractivo (máx 60 caracteres)' : '';
const subjectJson = canal === 'email' ? '"asunto aquí"' : 'null';
const webSection = websiteContext ? '\n\nSU SITIO WEB (extracto):\n' + websiteContext : '';

const prompt = 'Sos un experto en ventas consultivas para Pluxow, agencia de marketing digital en Argentina.\n\n'
  + 'SERVICIOS DE PLUXOW:\n'
  + '- Gestión de redes sociales (Instagram, Facebook, TikTok)\n'
  + '- Producción de contenido (fotos, videos, reels)\n'
  + '- Publicidad digital (Meta Ads, Google Ads)\n'
  + '- Diseño de identidad visual y branding\n'
  + '- Desarrollo web y landing pages\n'
  + '- Email marketing y automatizaciones\n'
  + '- Gestión de reputación online y reseñas\n\n'
  + 'DATOS DEL PROSPECTO:\n'
  + '- Empresa/Persona: ' + flyerData.empresa + '\n'
  + '- Rubro: ' + flyerData.sector + '\n'
  + '- Descripción: ' + flyerData.descripcion + '\n'
  + '- Canal de contacto elegido: ' + canalLabel
  + webSection + '\n\n'
  + 'Tu tarea:\n'
  + '1. Identificá 3 pain points específicos de este negocio que Pluxow puede resolver (concretos, no genéricos)\n'
  + '2. Escribí un mensaje de primer contacto para ' + canalLabel + ':\n'
  + '   - Tono cercano, amigable, no invasivo\n'
  + '   - Mencioná algo específico de su negocio que muestre que lo conocés\n'
  + '   - Proponé una llamada o videollamada gratuita de 20 minutos\n'
  + '   - Largo: ' + maxLength
  + subjectInstruction + '\n\n'
  + 'Respondé SOLO con este JSON sin markdown:\n'
  + '{\n'
  + '  "pain_points": ["punto 1", "punto 2", "punto 3"],\n'
  + '  "draft": "el mensaje completo",\n'
  + '  "subject": ' + subjectJson + '\n'
  + '}';

const body = {
  model: 'claude-sonnet-4-6',
  max_tokens: 1024,
  messages: [{ role: 'user', content: prompt }]
};

return {
  json: {
    claudeBody: JSON.stringify(body),
    flyerData,
    canal
  }
};

const response = $input.item.json;
const flyerData = $('Build Draft Request').item.json.flyerData;
const canal = $('Build Draft Request').item.json.canal;

const text = response.content[0].text;
const clean = text.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();

let draftData;
try {
  draftData = JSON.parse(clean);
} catch(e) {
  throw new Error('No se pudo parsear el draft: ' + text);
}

const phone = flyerData.telefono;
const instagram = flyerData.instagram;
const email = flyerData.email;
const draft = draftData.draft;
const encoded = encodeURIComponent(draft);

const links = {
  whatsapp: phone
    ? 'https://wa.me/' + phone + '?text=' + encoded
    : null,
  instagram: instagram
    ? 'https://instagram.com/' + instagram
    : null,
  mailto: email
    ? (draftData.subject
        ? 'mailto:' + email + '?subject=' + encodeURIComponent(draftData.subject) + '&body=' + encoded
        : 'mailto:' + email + '?body=' + encoded)
    : null
};

return {
  json: {
    empresa: flyerData.empresa,
    sector: flyerData.sector,
    descripcion: flyerData.descripcion,
    contacto: {
      canal,
      email: email || null,
      telefono: phone || null,
      instagram: instagram || null
    },
    pain_points: draftData.pain_points,
    draft,
    subject: draftData.subject || null,
    links
  }
};
